			if (Bind != null)
			{
				((IJavaObject)(object)menu).BindRaw(Bind);
			}
			ApplyHandler?.Invoke(menu, owner);
		}

		public void Clear(IMenu menu, IReadOnlyMetadataContext? metadata)
		{
			ClearHandler?.Invoke(menu);
			ClearMenu(menu);
		}
	}
