		private AndroidViewLifecycleState(long value, string? name = null, bool register = true)
			: base(value, name, register)
		{
		}

		public static ViewLifecycleState? TryParseNativeChanging(object view, int state)
		{
			switch (state)
			{
			case 1:
				return Finishing;
			case 2:
				return FinishingAfterTransition;
			case 3:
				if (!(view is IActivityView activityView) || !ActivityMugenExtensions.IsTaskRoot(activityView))
				{
					return BackPressing;
				}
				return BackPressingTaskRoot;
			case 4:
				return NewIntentChanging;
			case 5:
				return ConfigurationChanging;
			case 6:
				return Creating;
			case 7:
				return Destroying;
			case 8:
				return Pausing;
			case 9:
				return Restarting;
			case 10:
				return Resuming;
			case 11:
				return SavingState;
			case 12:
				return Starting;
			case 13:
				return Stopping;
			case 14:
				return PostCreating;
			case 16:
				return OptionsItemSelecting;
			case 15:
				return CreatingOptionsMenu;
			case 17:
				return Dismissing;
			case 18:
				return DismissingAllowingStateLoss;
			case 19:
				return Canceling;
			case 22:
				return ViewLifecycleState.Appearing;
			case 23:
				return ViewLifecycleState.Disappearing;
			default:
				return null;
			}
		}

		public static ViewLifecycleState? TryParseNativeChanged(object view, int state)
		{
			switch (state)
			{
			case 1:
				return Finished;
			case 2:
				return FinishedAfterTransition;
			case 3:
				if (!(view is IActivityView activityView2) || !ActivityMugenExtensions.IsTaskRoot(activityView2))
				{
					return BackPressed;
				}
				return BackPressedTaskRoot;
			case 4:
				return NewIntentChanged;
			case 5:
				return ConfigurationChanged;
			case 6:
				return Created;
			case 7:
				if (!(view is IActivityView { IsFinishing: not false }))
				{
					return Destroyed;
				}
				return DestroyedCloseable;
			case 8:
				return Paused;
			case 9:
				return Restarted;
			case 10:
				return Resumed;
			case 11:
				return SavedState;
			case 12:
				return Started;
			case 13:
				return Stopped;
			case 14:
				return PostCreated;
			case 16:
				return OptionsItemSelected;
			case 15:
				return CreatedOptionsMenu;
			case 17:
				return Dismissed;
			case 18:
				return DismissedAllowingStateLoss;
			case 19:
				return Canceled;
			case 22:
				return ViewLifecycleState.Appeared;
			case 23:
				return ViewLifecycleState.Disappeared;
			default:
				return null;
			}
		}
	}
