	public sealed class ItemsSourceBindableCollectionAdapter : BindableCollectionAdapter
	{
		private readonly IEqualityComparer<object?>? _diffComparer;

		private ListSlim<IItemsSourceObserver> _observers;

		private int _diffSupportedCount;

		private bool _isAlive;

		public int MaxChangesLimit { get; init; } = 500;

		public int AsyncChangesLimit { get; init; } = 5000;

		protected override bool IsAlive => _isAlive;

		public override IEqualityComparer<object> DiffComparer => _diffComparer ?? ReferenceEqualityComparer.Instance;

		public ItemsSourceBindableCollectionAdapter(IEqualityComparer<object?>? diffComparer)
		{
			_diffComparer = diffComparer;
			_observers = new ListSlim<IItemsSourceObserver>(2);
			_isAlive = true;
		}

		public void AddObserver(IItemsSourceObserver observer)
		{
			Should.NotBeNull(observer, "observer");
			_observers.Add(observer);
			if (observer.IsDiffUtilSupported)
			{
				_diffSupportedCount++;
			}
		}

		public void RemoveObserver(IItemsSourceObserver observer)
		{
			Should.NotBeNull(observer, "observer");
			_observers.Remove(observer);
			if (observer.IsDiffUtilSupported)
			{
				_diffSupportedCount--;
			}
		}

		protected override async void Invalidate(int version, PooledReadOnlyList<CollectionChangedEvent> events, PooledReadOnlyDictionarySlim<object, int> reloads, CollectionChangedAction flags)
		{
			PooledListSlim<object?> newItems = default(PooledListSlim<object>);
			CollectionDiff<CollectionDiffHandler> diff = default(CollectionDiff<CollectionDiffHandler>);
			bool isAsync = false;
			try
			{
				for (int i = 0; i < _observers.Count; i++)
				{
					GetObserver(_observers[i])?.BeginUpdate();
				}
				try
				{
					if (_diffSupportedCount == 0)
					{
						if (flags.HasFlagEx(CollectionChangedAction.Reset))
						{
							foreach (CollectionChangedEvent item in events)
							{
								item.ApplyToSource(ref Items);
							}
							OnReset();
						}
						else
						{
							RaiseEvents(events);
						}
						return;
					}
					if (!flags.HasFlagEx(CollectionChangedAction.Reset) && !flags.HasFlagEx(CollectionChangedAction.Add | CollectionChangedAction.Remove))
					{
						RaiseEvents(events);
						return;
					}
					newItems = new PooledListSlim<object>(Items.ReadOnlySpan);
					foreach (CollectionChangedEvent item2 in events)
					{
						item2.ApplyToSource(ref newItems);
					}
				}
				finally
				{
					BindableCollectionAdapter.ReleasePendingEvents(events);
				}
				if (Items.Count == 0)
				{
					Items.Reset(newItems.ReadOnlySpan);
					if (newItems.Count != 0)
					{
						OnInserted(0, newItems.Count);
					}
					return;
				}
				if (newItems.Count == 0)
				{
					int count = Items.Count;
					Items.Clear();
