	public sealed class MenuItemsSourceGenerator : DiffableBindableCollectionAdapter
	{
		public IMenu Menu { get; }

		public IMenuItemTemplate ItemTemplate { get; }

		protected override bool IsAlive => ((IJavaObject)Menu).Handle != (IntPtr)IntPtr.Zero;

		private MenuItemsSourceGenerator(IMenu menu, IMenuItemTemplate itemTemplate)
		{
			Should.NotBeNull(itemTemplate, "itemTemplate");
			Menu = menu;
			ItemTemplate = itemTemplate;
		}

		public static MenuItemsSourceGenerator? TryGet(IMenu menu)
		{
			menu.AttachedValues<IMenu>().TryGet("`@mi", out object value);
			return value as MenuItemsSourceGenerator;
		}

		public static MenuItemsSourceGenerator GetOrAdd(IMenu menu)
		{
			Should.NotBeNull(menu, "menu");
			AttachedValueStorage attachedValueStorage = menu.AttachedValues<IMenu>().BatchUpdate();
			try
			{
				if (!attachedValueStorage.TryGet((ReadOnlySpan<char>)"`@mi", out MenuItemsSourceGenerator value))
				{
					value = new MenuItemsSourceGenerator(menu, menu.ItemTemplate());
					attachedValueStorage.Set("`@mi", value);
				}
				return value;
			}
			finally
			{
				((IDisposable)attachedValueStorage/*cast due to .constrained prefix*/).Dispose();
			}
		}

		protected override void OnAdded(object? item, int index)
		{
			base.OnAdded(item, index);
			if (index == Menu.Size())
			{
				ItemTemplate.Apply(Menu, index, index, item, null);
			}
			else
			{
				Reload();
			}
		}

		protected override void OnMoved(int oldIndex, int newIndex)
		{
			base.OnMoved(oldIndex, newIndex);
			Reload();
		}

		protected override void OnRemoved(int index)
		{
			base.OnRemoved(index);
			if (index == Menu.Size() - 1)
			{
				RemoveMenuItem(index);
			}
			else
			{
				Reload();
			}
		}

		protected override void OnReplaced(object? newItem, int index)
		{
			base.OnReplaced(newItem, index);
			RemoveMenuItem(index);
			ItemTemplate.Apply(Menu, index, index, newItem, null);
		}

		protected override void OnReset(ReadOnlySpan<object?> items)
		{
			base.OnReset(items);
			Reload();
		}

		private void RemoveMenuItem(int id)
		{
			IMenuItem menuItem = Menu.FindItem(id);
			ItemTemplate.Clear(menuItem, null);
			Menu.RemoveItem(id);
		}

		private void Reload()
		{
			Clear();
			for (int i = 0; i < Items.Count; i++)
			{
				ItemTemplate.Apply(Menu, i, i, Items[i], null);
			}
		}

		private void Clear()
		{
			int num = Menu.Size();
			for (int i = 0; i < num; i++)
			{
				ItemTemplate.Clear(Menu.GetItem(i), null);
			}
			Menu.Clear();
		}
	}
